# Combinar todos
TRANSLATIONS.update(HH)
TRANSLATIONS.update(OPTMENU)
TRANSLATIONS.update(USAGEHLP)
TRANSLATIONS.update(WIZHELP)
TRANSLATIONS.update(ORACLES)
TRANSLATIONS.update(BOGUSMON)
TRANSLATIONS.update(RUMORS_TRU)
TRANSLATIONS.update(RUMORS_FAL)


def main():
    po = polib.pofile(PO_FILE)
    stats = {}
    targets = [
        ("dat/hh", "dat/hh"),
        ("dat/optmenu", "dat/optmenu"),
        ("dat/usagehlp", "dat/usagehlp"),
        ("dat/wizhelp", "dat/wizhelp"),
        ("dat/oracles.txt", "dat/oracles.txt"),
        ("dat/bogusmon.txt", "dat/bogusmon.txt"),
        ("dat/rumors.tru", "dat/rumors.tru"),
        ("dat/rumors.fal", "dat/rumors.fal"),
    ]

    for target, label in targets:
        total = 0
        translated = 0
        for entry in po:
            is_target = any(ref[0] == target for ref in entry.occurrences)
            if not is_target:
                continue
            total += 1
            if entry.msgid in TRANSLATIONS:
                entry.msgstr = TRANSLATIONS[entry.msgid]
                translated += 1
        stats[label] = (total, translated)

    po.save(PO_FILE)

    print("=" * 60)
    print(f"{'Archivo':<25} {'Total':>8} {'Traducidas':>12} {'Pendientes':>12}")
    print("=" * 60)
    total_all = 0
    translated_all = 0
    for label, (total, translated) in stats.items():
        pending = total - translated
        print(f"{label:<25} {total:>8} {translated:>12} {pending:>12}")
        total_all += total
        translated_all += translated
    print("=" * 60)
    print(
        f"{'TOTAL':<25} {total_all:>8} {translated_all:>12} {total_all - translated_all:>12}"
    )
    print("=" * 60)

    if translated_all < total_all:
        print("\n--- Entradas sin traducir ---")
        for target, label in targets:
            for entry in po:
                is_target = any(ref[0] == target for ref in entry.occurrences)
                if is_target and not entry.msgstr:
                    line = entry.occurrences[0][1]
                    print(f"  [{label}:{line}] {entry.msgid[:80]}")


if __name__ == "__main__":
    main()
